import { useState, useId } from 'react';
import type { KeyboardEvent } from 'react';
import {
  Screen,
  Card,
  Grid,
  Stack,
  Row,
  TextField,
  SelectField,
  Button,
  Alert,
  Badge,
  KeyBar,
} from '@nexti/ds';

type Errors = Partial<Record<'ORDEN' | 'EMPRESA', string>>;
type Status =
  | { tone: 'info' | 'success' | 'warning' | 'error'; text: string }
  | null;

const digits = (v: string, max: number) => v.replace(/\D/g, '').slice(0, max);

export default function PagoOrdenes({ navigate }: { navigate: (to: string) => void }) {
  const claveId = useId();

  const [orden, setOrden] = useState('');
  const [empresa, setEmpresa] = useState('');
  const [servic, setServic] = useState('');
  const [tipcta, setTipcta] = useState('');
  const [cuenta, setCuenta] = useState('');
  const [valor, setValor] = useState('');
  const [canal, setCanal] = useState('WEB');
  const [clave, setClave] = useState('');

  const [errors, setErrors] = useState<Errors>({});
  const [status, setStatus] = useState<Status>(null);
  const [paid, setPaid] = useState(false);

  const onValor = (v: string) => {
    const n = v.replace(',', '.');
    if (/^\d{0,9}(\.\d{0,2})?$/.test(n)) setValor(n);
  };

  const pagar = () => {
    const e: Errors = {};
    if (!orden) e.ORDEN = 'El número de orden es obligatorio';
    if (!empresa) e.EMPRESA = 'La empresa es obligatoria';
    setErrors(e);
    if (Object.keys(e).length > 0) {
      setPaid(false);
      setStatus({ tone: 'error', text: 'Complete los campos obligatorios para realizar el pago.' });
      return;
    }
    setPaid(true);
    setStatus({
      tone: 'success',
      text: `Pago de la orden ${orden} enviado correctamente por el canal ${canal}.`,
    });
  };

  const volver = () => navigate('SCR-PAGOMEN');

  const cancelar = () => {
    setOrden('');
    setEmpresa('');
    setServic('');
    setTipcta('');
    setCuenta('');
    setValor('');
    setCanal('WEB');
    setClave('');
    setErrors({});
    setPaid(false);
    setStatus({ tone: 'info', text: 'Operación cancelada. Los datos fueron limpiados.' });
  };

  const onKeyDown = (ev: KeyboardEvent<HTMLDivElement>) => {
    const tag = (ev.target as HTMLElement).tagName;
    if (ev.key === 'Enter' && tag === 'INPUT') {
      ev.preventDefault();
      pagar();
    } else if (ev.key === 'F3') {
      ev.preventDefault();
      volver();
    } else if (ev.key === 'F12') {
      ev.preventDefault();
      cancelar();
    }
  };

  return (
    <Screen
      title="Pago de órdenes"
      code="PAGOORD"
      keys={
        <KeyBar
          actions={[
            { key: 'ENTER', label: 'Pagar', onPress: pagar, primary: true },
            { key: 'PF3', label: 'Volver', onPress: volver },
            { key: 'PF12', label: 'Cancelar', onPress: cancelar },
          ]}
        />
      }
    >
      <style>{`
        .pago-valor input { text-align: right; font-variant-numeric: tabular-nums; }
        .pago-valor { text-align: right; }
        .pago-valor label { text-align: left; display: block; }
      `}</style>
      <div onKeyDown={onKeyDown}>
        <Stack>
          <div data-field="MENSAJE" aria-live="polite">
            {status ? (
              <Alert tone={status.tone}>{status.text}</Alert>
            ) : (
              <Alert tone="info">
                Ingrese los datos de la orden y presione Pagar. Los campos con * son obligatorios.
              </Alert>
            )}
          </div>

          <Card title="Datos de la orden">
            <Grid columns={2}>
              <div data-field="ORDEN">
                <TextField
                  label="Número de orden"
                  required
                  numeric
                  maxLength={7}
                  hint="Hasta 7 dígitos"
                  error={errors.ORDEN}
                  value={orden}
                  onChange={(v: string) => setOrden(digits(v, 7))}
                />
              </div>
              <div data-field="EMPRESA">
                <TextField
                  label="Empresa"
                  required
                  numeric
                  maxLength={5}
                  hint="Hasta 5 dígitos"
                  error={errors.EMPRESA}
                  value={empresa}
                  onChange={(v: string) => setEmpresa(digits(v, 5))}
                />
              </div>
              <div data-field="SERVIC">
                <TextField
                  label="Servicio"
                  maxLength={10}
                  hint="Hasta 10 caracteres"
                  value={servic}
                  onChange={(v: string) => setServic(v.toUpperCase().slice(0, 10))}
                />
              </div>
              <div data-field="TIPCTA">
                <TextField
                  label="Tipo de cuenta"
                  maxLength={3}
                  hint="3 caracteres, por ejemplo AHO o CTE"
                  value={tipcta}
                  onChange={(v: string) => setTipcta(v.toUpperCase().slice(0, 3))}
                />
              </div>
              <div data-field="CUENTA">
                <TextField
                  label="Cuenta"
                  numeric
                  maxLength={10}
                  hint="Hasta 10 dígitos"
                  value={cuenta}
                  onChange={(v: string) => setCuenta(digits(v, 10))}
                />
              </div>
              <div data-field="VALOR" className="pago-valor">
                <TextField
                  label="Valor"
                  numeric
                  maxLength={12}
                  hint="Hasta 9 enteros y 2 decimales, por ejemplo 125000.50"
                  value={valor}
                  onChange={onValor}
                />
              </div>
            </Grid>
          </Card>

          <Card title="Canal y aprobación">
            <Grid columns={2}>
              <div data-field="CANAL">
                <SelectField
                  label="Canal (WEB/OFI)"
                  hint="Valor inicial: WEB"
                  options={[
                    { value: 'WEB', label: 'WEB - Canal web' },
                    { value: 'OFI', label: 'OFI - Oficina' },
                  ]}
                  value={canal}
                  onChange={(v: string) => setCanal(v)}
                />
              </div>
              <div data-field="CLAVE">
                <label htmlFor={claveId} style={{ display: 'block', fontWeight: 600, marginBottom: 4 }}>
                  Clave de aprobación
                </label>
                <input
                  id={claveId}
                  type="password"
                  autoComplete="off"
                  maxLength={6}
                  value={clave}
                  aria-describedby={`${claveId}-hint`}
                  onChange={(e) => setClave(e.target.value.slice(0, 6))}
                  style={{ width: '100%', padding: '8px', boxSizing: 'border-box' }}
                />
                <div id={`${claveId}-hint`} style={{ fontSize: 12, opacity: 0.75, marginTop: 4 }}>
                  Hasta 6 caracteres. No se muestra en pantalla al digitar.
                </div>
              </div>
            </Grid>
          </Card>

          <Row>
            <Button variant="primary" shortcut="ENTER" onClick={pagar}>
              Pagar
            </Button>
            <Button variant="secondary" shortcut="PF3" onClick={volver}>
              Volver
            </Button>
            <Button variant="danger" shortcut="PF12" onClick={cancelar}>
              Cancelar
            </Button>
            {paid && (
              <Button variant="ghost" onClick={() => navigate('SCR-PAGORES')}>
                Ver resultado del pago
              </Button>
            )}
            <Badge>{paid ? 'Pago enviado' : 'Pendiente de pago'}</Badge>
          </Row>
        </Stack>
      </div>
    </Screen>
  );
}
