```tsx
import { useState } from 'react'
import type { FormEvent } from 'react'
import { Screen, Card, Grid, Stack, TextField, Button, Alert } from '@nexti/ds'
import { ApiError } from '../api/client'
import type { PayOrderRequest } from '../api/client'
import type { ScreenProps } from './types'

type Tone = 'info' | 'success' | 'warning' | 'error'
type Status = { tone: Tone; text: string } | null
type Errors = Partial<Record<'ORDEN' | 'EMPRESA', string>>

const digits = (v: string, max: number) => v.replace(/\D/g, '').slice(0, max)

/** Local timestamp without timezone, e.g. 2025-01-31T14:05:09 */
function localTimestamp(): string {
  const d = new Date()
  const p = (n: number) => String(n).padStart(2, '0')
  return (
    `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}` +
    `T${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`
  )
}

export default function PagoordScreen({ api, navigate }: ScreenProps) {
  const [orden, setOrden] = useState('')
  const [empresa, setEmpresa] = useState('')
  const [servic, setServic] = useState('')
  const [tipcta, setTipcta] = useState('')
  const [cuenta, setCuenta] = useState('')
  const [valor, setValor] = useState('')
  const [canal, setCanal] = useState('WEB')
  const [clave, setClave] = useState('')

  const [errors, setErrors] = useState<Errors>({})
  const [status, setStatus] = useState<Status>(null)
  const [busy, setBusy] = useState(false)

  const onValor = (v: string) => {
    const n = v.replace(',', '.')
    if (/^\d{0,8}(\.\d{0,2})?$/.test(n)) setValor(n)
  }

  const submit = async (ev: FormEvent) => {
    ev.preventDefault()
    if (busy) return

    const e: Errors = {}
    if (!orden.trim()) e.ORDEN = 'El número de orden es obligatorio'
    if (!empresa.trim()) e.EMPRESA = 'La empresa es obligatoria'
    setErrors(e)
    if (Object.keys(e).length > 0) {
      setStatus({ tone: 'error', text: 'Complete los campos obligatorios para realizar el pago.' })
      return
    }

    const amount = valor === '' || valor === '.' ? 0 : Number(valor)
    const request: PayOrderRequest = {
      orderNumber: Number(orden),
      company: Number(empresa),
      service: servic,
      accountType: tipcta,
      account: cuenta,
      amount,
      channel: canal,
      processingDate: localTimestamp(),
    }

    setBusy(true)
    setStatus(null)
    try {
      const res = await api.payOrder(request)
      setStatus({ tone: 'success', text: res.message })
    } catch (err) {
      if (err instanceof ApiError) {
        setStatus({ tone: 'error', text: err.message })
      } else {
        setStatus({ tone: 'error', text: 'No fue posible completar el pago.' })
      }
    } finally {
      setBusy(false)
    }
  }

  const volver = () => navigate('SCR-PAGOMEN')

  const cancelar = () => {
    setOrden('')
    setEmpresa('')
    setServic('')
    setTipcta('')
    setCuenta('')
    setValor('')
    setCanal('WEB')
    setClave('')
    setErrors({})
    setStatus({ tone: 'info', text: 'Operación cancelada. Los datos fueron limpiados.' })
  }

  return (
    <Screen title="PAGO DE ORDENES">
      <form onSubmit={submit} noValidate>
        <Stack>
          <div data-field="MENSAJE" aria-live="polite">
            <Alert tone={status ? status.tone : 'info'}>
              <p>
                {status
                  ? status.text
                  : 'Ingrese los datos de la orden y presione Pagar. Los campos obligatorios están marcados.'}
              </p>
            </Alert>
          </div>

          <Card title="Datos de la orden">
            <Grid columns={2}>
              <div data-field="ORDEN">
                <TextField
                  label="ORDEN"
                  required
                  numeric
                  maxLength={7}
                  hint="Hasta 7 dígitos"
                  error={errors.ORDEN}
                  value={orden}
                  onChange={(v: string) => setOrden(digits(v, 7))}
                />
              </div>
              <div data-field="EMPRESA">
                <TextField
                  label="EMPRESA"
                  required
                  numeric
                  maxLength={5}
                  hint="Hasta 5 dígitos"
                  error={errors.EMPRESA}
                  value={empresa}
                  onChange={(v: string) => setEmpresa(digits(v, 5))}
                />
              </div>
              <div data-field="SERVIC">
                <TextField
                  label="SERVIC"
                  maxLength={10}
                  hint="Hasta 10 caracteres"
                  value={servic}
                  onChange={(v: string) => setServic(v.toUpperCase().slice(0, 10))}
                />
              </div>
              <div data-field="TIPCTA">
                <TextField
                  label="TIPCTA"
                  maxLength={3}
                  hint="3 caracteres, por ejemplo AHO o CTE"
                  value={tipcta}
                  onChange={(v: string) => setTipcta(v.toUpperCase().slice(0, 3))}
                />
              </div>
              <div data-field="CUENTA">
                <TextField
                  label="CUENTA"
                  numeric
                  maxLength={10}
                  hint="Hasta 10 dígitos"
                  value={cuenta}
                  onChange={(v: string) => setCuenta(digits(v, 10))}
                />
              </div>
              <div data-field="VALOR">
                <TextField
                  label="VALOR"
                  numeric
                  maxLength={11}
                  hint="Hasta 8 enteros y 2 decimales, por ejemplo 125000.50"
                  value={valor}
                  onChange={onValor}
                />
              </div>
            </Grid>
          </Card>

          <Card title="Canal y aprobación">
            <Grid columns={2}>
              <div data-field="CANAL">
                <TextField
                  label="CANAL"
                  maxLength={3}
                  hint="WEB u OFI. Valor inicial: WEB"
                  value={canal}
                  onChange={(v: string) => setCanal(v.toUpperCase().slice(0, 3))}
                />
              </div>
              <div data-field="CLAVE">
                <TextField
                  label="CLAVE"
                  type="password"
                  maxLength={6}
                  hint="Hasta 6 caracteres. No se muestra en pantalla al digitar."
                  value={clave}
                  onChange={(v: string) => setClave(v.slice(0, 6))}
                />
              </div>
            </Grid>
          </Card>

          <Stack>
            <Button data-action="ENTER" type="submit" variant="primary" disabled={busy}>
              PAGAR
            </Button>
            <Button data-action="PF3" type="button" variant="secondary" onClick={volver}>
              VOLVER
            </Button>
            <Button data-action="PF12" type="button" variant="danger" onClick={cancelar}>
              CANCELAR
            </Button>
          </Stack>
        </Stack>
      </form>
    </Screen>
  )
}
